import sys
import select
import time
import cv2
import rclpy
from rclpy.node import Node
from sensor_msgs.msg import Image
from std_msgs.msg import Float64, Int32MultiArray
from geometry_msgs.msg import Twist
from cv_bridge import CvBridge 


class PIDController:
    def __init__(self, kp: float = 50.0, ki: float = 0.0, kd: float = 10.0):
        self.kp = kp
        self.ki = ki
        self.kd = kd
        self.last_error = 0.0
        self.integral = 0.0

    def compute(self, error: float, dt: float) -> float:
        if dt <= 0:
            return 0.0

        p_term = self.kp * error
        self.integral += error * dt
        i_term = self.ki * self.integral
        derivative = (error - self.last_error) / dt
        d_term = self.kd * derivative

        self.last_error = error
        return p_term + i_term + d_term
    
class LineTrackerNode(Node):
    def __init__(self):
        super().__init__('line_tracker_node')

        # Buka kamera dengan cv2.VideoCapture (sesuai kode asli Anda)
        self.cap = cv2.VideoCapture(0, cv2.CAP_V4L2)
        if not self.cap.isOpened():
            self.get_logger().error("Cannot open camera")
            sys.exit(1)

        self.bridge = CvBridge()

        # Publisher untuk gambar debug (pengganti cv2.imshow)
        self.debug_pub = self.create_publisher(
            Image, '/line_tracker/debug_image', 10
        )

        # Publisher untuk normalized_error (berguna untuk node PID/controller)
        self.error_pub = self.create_publisher(
            Float64, '/line_tracker/normalized_error', 10
        )
        # Penambahan Publisher & Parameter
        #=======================================================================
        # Publisher untuk Motor PWM [PWM Kiri, PWM Kanan]
        self.pwm_pub = self.create_publisher(
            Int32MultiArray, '/motor_pwm', 10
        )
        
        # Publisher standar kecepatan robot ROS 2 (/cmd_vel)
        self.cmd_vel_pub = self.create_publisher(
            Twist, '/cmd_vel', 10
        )
       
        # Parameter PID & Speed
        self.declare_parameter('kp', 60.0)
        self.declare_parameter('ki', 0.0)
        self.declare_parameter('kd', 15.0)
        self.declare_parameter('base_speed', 100)  # PWM acuan jalan lurus (0-255)

        # Inisialisasi PID
        kp = self.get_parameter('kp').value
        ki = self.get_parameter('ki').value
        kd = self.get_parameter('kd').value
        self.pid = PIDController(kp=kp, ki=ki, kd=kd)
        self.last_time = time.time()
        # ======================================================================
        # Timer pengganti while True (30 FPS)
        # PENTING: jangan pakai while True di ROS, akan blocking executor
        self.timer = self.create_timer(1.0 / 30.0, self.timer_callback)

        self.get_logger().info("Line tracker Node with PID started. Press 'q' on OPenCV window to quit(cv2.VideoCapture mode).")

    def timer_callback(self):
        ret, frame = self.cap.read()
        if not ret:
            self.get_logger().warn("Can't receive frame. Skipping...")
            return

        height, width, _ = frame.shape

        # Define Region of Interest (ROI)
        roi_top = int(height * 0.70)
        roi_bottom = int(height * 0.90)
        roi_left = int(width * 0.20)
        roi_right = int(width * 0.80)

        # Cut image to ROI
        roi = frame[roi_top:roi_bottom, roi_left:roi_right]
        gray = cv2.cvtColor(roi, cv2.COLOR_BGR2GRAY)

        # Gaussian Blur
        blurred = cv2.GaussianBlur(gray, (3, 3), 0)

        _, thresh = cv2.threshold(
            blurred, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU
        )

        moments = cv2.moments(thresh)

        # Draw visualization overlay
        debug = frame.copy()
        cv2.rectangle(debug, (roi_left, roi_top), (roi_right, roi_bottom), (0, 255, 0), 2)
        cv2.line(debug, (int(width / 2), 0), (int(width / 2), height), (255, 0, 0), 1)

        # Jika tidak ada garis, skip frame ini (JANGAN return 0 / exit node)
        if moments["m00"] == 0:
            # Tetap publish gambar debug supaya bisa dilihat di rqt
            self._stop_motors()
            self._publish_debug(debug)
            self._handle_display_and_key(debug)
            return

        # Calculate the center of mass of the line in x
        center_of_x = int(moments["m10"] / moments["m00"])

        # Normalize offset
        image_center = (roi_right - roi_left) / 2
        error_pixels = center_of_x - image_center
        normalized_error = error_pixels / image_center

        # Draw centroid
        centroid_y = roi_top + int((roi_bottom - roi_top) / 2)
        cv2.circle(
            debug,
            (center_of_x + roi_left, centroid_y),
            5,
            (100, 0, 255),
            -1,
        )
        # Publish gambar debug (pengganti cv2.imshow)
        self._publish_debug(debug)

        # Publish nilai error
        err_msg = Float64()
        err_msg.data = float(normalized_error)
        self.error_pub.publish(err_msg)

        # print(error_pixels)
        
        # Penambahan Kalkulasi PID dan Pengiriman Data ke Motor
        #==================================================================================
        current_time = time.time()
        dt = current_time - self.last_time
        self.last_time = current_time

        # Update parameter PID secara dinamis jika diubah via terminal
        self.pid.kp = self.get_parameter('kp').value
        self.pid.ki = self.get_parameter('ki').value
        self.pid.kd = self.get_parameter('kd').value
        base_speed = self.get_parameter('base_speed').value

        # Hitung Koreksi PID dari normalized_error
        pid_output = self.pid.compute(normalized_error, dt)

        # Perhitungan PWM Kiri dan Kanan
        pwm_kiri = base_speed + pid_output
        pwm_kanan = base_speed - pid_output

        # Constrain PWM (Batas aman 0 - 255)
        pwm_kiri = max(0, min(255, int(round(pwm_kiri))))
        pwm_kanan = max(0, min(255, int(round(pwm_kanan))))

        print(f"pwm_kiri: {pwm_kiri}, pwm_kanan: {pwm_kanan}\n")

        # 1. Publish Topik PWM Roda (/motor_pwm)
        pwm_msg = Int32MultiArray()
        pwm_msg.data = [pwm_kiri, pwm_kanan]
        self.pwm_pub.publish(pwm_msg)

        # 2. Publish Topik Standard ROS 2 Velocity (/cmd_vel)
        twist_msg = Twist()
        twist_msg.linear.x = float(base_speed) / 255.0
        twist_msg.angular.z = -float(pid_output) / 100.0
        self.cmd_vel_pub.publish(twist_msg)
        # ======================================================================

        # PEMANGGILAN FUNGSI HANDLER DITAMBAHKAN DI SINI
        self._handle_display_and_key(debug)

    def _stop_motors(self):
        """Menghentikan pergerakan motor jika garis tidak terdeteksi."""
        pwm_msg = Int32MultiArray()
        pwm_msg.data = [0, 0]
        self.pwm_pub.publish(pwm_msg)

        twist_msg = Twist()
        self.cmd_vel_pub.publish(twist_msg)

    def _handle_display_and_key(self, cv_image):
        cv2.imshow("Line Detection Debug", cv_image)
        key = cv2.waitKey(1) & 0xFF
        if key == ord('q'):
            self.get_logger().info("Tombol 'q' ditekan. Mematikan node...")
            # Langsung tutup window OpenCV
            self._stop_motors()
            cv2.destroyAllWindows()
            # Matikan ROS spin
            rclpy.shutdown()

    def _check_terminal_q_pressed(self):
        """Mengecek apakah pengguna mengetik 'q' di Terminal tanpa menekan Enter"""
        if sys.stdin in select.select([sys.stdin], [], [], 0)[0]:
            line = sys.stdin.read(1)
            if line.lower() == 'q':
                return True
        return False

    def _shutdown_node(self):
        self.get_logger().info("Mematikan Node...")
        self._stop_motors()
        cv2.destroyAllWindows()
        if rclpy.ok():
            rclpy.shutdown()

    def _publish_debug(self, cv_image):
        try:
            msg = self.bridge.cv2_to_imgmsg(cv_image, "bgr8")
            self.debug_pub.publish(msg)
        except Exception as e:
            self.get_logger().error(f"Failed to publish debug image: {e}")

    def destroy_node(self):
        self.get_logger().info("Releasing camera...")
        self._stop_motors()
        if self.cap is not None and self.cap.isOpened():
            self.cap.release()
        cv2.destroyAllWindows()
        super().destroy_node()

def main(args=None):
    rclpy.init(args=args)
    node = LineTrackerNode()
  # Ubah mode terminal sementara (Linux/Ubuntu)
    import tty
    import termios
    old_settings = None
    try:
        if sys.stdin.isatty():
            old_settings = termios.tcgetattr(sys.stdin)
            tty.setcbreak(sys.stdin.fileno())

        rclpy.spin(node)
    except (KeyboardInterrupt, rclpy.executors.ExternalShutdownException):
        pass
    finally:
        if old_settings:
            termios.tcsetattr(sys.stdin, termios.TCSADRAIN, old_settings)
        node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()


if __name__ == "__main__":
    main()